using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed HasIndex for Cosmos (no secondary indexes).
            // Removed: entity.HasIndex(b => b.Name);

            // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
            // Preserve existing documents by keeping the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 3: Id format changed from "EntityType|Key" to just "Key".
            // Preserve existing id format for compatibility with stored documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();
        });
    }
}

